import json
import datetime

MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
CURS = [('debtUSD', 'Dolar', 'USD'), ('debtEUR', 'Euro', 'EUR'), ('debtGBP', 'İngiliz Sterlini', 'GBP')]
OLD = {'debtTL': 'debt_tl', 'debtUSD': 'debt_usd', 'debtEUR': 'debt_eur', 'debtGBP': 'debt_gbp'}
APO = chr(39)

def flat(prefix):
    o = {}
    for f in ['statementDebt', 'minPayment', 'remainingDebt', 'remainingMinPayment', 'currentPeriodExpense', 'totalDebt', 'transferAmount', 'statementPaymentStatus', 'totalDebtPaymentStatus', 'remainAutomaticPaymentAmount']:
        try:
            v = vars.get(prefix + f)
        except Exception:
            v = None
        if v is not None and str(v) != 'null':
            o[f] = v
    return o

def BL(name):
    b = flat('cards_balance_response.data.data.' + name + '.')
    if not b:
        v = vars.get(OLD.get(name, ''))
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except Exception:
                v = None
        if isinstance(v, dict):
            b = v
    return b if isinstance(b, dict) else {}

def T(name, alt):
    v = vars.get('cards_balance_response.data.data.' + name)
    if v is None or str(v) in ('', 'null'):
        v = vars.get(alt)
    if v is None or str(v) in ('', 'null'):
        return ''
    return str(v).strip()

def fv(b, k):
    try:
        return float(b.get(k) or 0)
    except Exception:
        return 0.0

def amt(x):
    try:
        x = round(float(x), 2)
    except Exception:
        x = 0.0
    if abs(x - round(x)) < 0.005:
        s = '{:,}'.format(int(round(x)))
    else:
        s = '{:,.2f}'.format(x)
    return s.replace(',', '#').replace('.', ',').replace('#', '.')

def pdate(s):
    try:
        return datetime.datetime.strptime(str(s).strip(), '%d.%m.%Y').date()
    except Exception:
        return None

def dstr(s):
    d = pdate(s)
    if d is None:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)

def digits(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())

def joinn(a):
    if len(a) == 1:
        return a[0]
    if len(a) == 2:
        return a[0] + ' ve ' + a[1]
    return ', '.join(a[:-1]) + ' ve ' + a[-1]

def tl_sentence(b):
    rd = fv(b, 'remainingDebt')
    rm = fv(b, 'remainingMinPayment')
    mp = fv(b, 'minPayment')
    sd = fv(b, 'statementDebt')
    if rd <= 0:
        return None
    if rm >= mp:
        return 'Türk Lirası borcunuz ' + amt(sd) + ' TL, ödenmesi gereken minimum tutar ' + amt(mp) + ' TL' + APO + 'dir.'
    if rm <= 0:
        return 'Türk Lirası borcunuz ' + amt(sd) + ' TL, kalan toplam borcunuz ' + amt(rd) + ' TL' + APO + 'dir. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
    return 'Türk Lirası borcunuz ' + amt(sd) + ' TL, ödenmesi gereken minimum tutar ' + amt(mp) + ' TL, kalan toplam borcunuz ' + amt(rd) + ' TL, kalan minimum ödeme tutarınız ' + amt(rm) + ' TL' + APO + 'dir.'

def fx_sentence(b, nm, cur):
    sd = fv(b, 'statementDebt')
    rd = fv(b, 'remainingDebt')
    mp = fv(b, 'minPayment')
    if sd <= 0 and rd <= 0:
        return None
    return nm + ' borcunuz ' + amt(sd) + ' ' + cur + ', kalan toplam borcunuz ' + amt(rd) + ' ' + cur + ', ödenmesi gereken minimum tutar ' + amt(mp) + ' ' + cur + APO + 'dir.'

def main():
    today = None
    try:
        today = datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        today = None
    tl = BL('debtTL')
    name = str(vars.get('chosen_card_name') or '').strip()
    last4 = digits(vars.get('chosen_last4') or '')
    stmt = T('statementDate', 'statement_date')
    lp = T('lastPayDate', 'last_pay_date')
    nxt = T('nextStatementDate', 'next_statement_date')
    email = str(vars.get('registered_email') or '').strip()
    ctype = str(vars.get('comm_type') or '').strip()
    card = 'Sonu ' + last4 + ' ile biten ' + ((name + ' kartınızın') if name else 'kartınızın')
    email_ok = '1' if (email != '' and ctype != 'Phone') else '0'
    offer = ''
    if email_ok == '1':
        offer = 'Ekstrenizi ' + email.replace('@', ' at ').replace('.', ' nokta ') + ' adresine göndermemi ister misiniz?'
    if stmt == '':
        s = 'Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır. İlk hesap kesim tarihiniz ' + dstr(nxt) + ' olacak.'
        return s, '', offer, email_ok
    sents = []
    nodebt = []
    if tl:
        s = tl_sentence(tl)
        if s:
            sents.append(s)
        else:
            nodebt.append('Türk Lirası')
    for key, nm, cur in CURS:
        b = BL(key)
        if not b:
            continue
        s = fx_sentence(b, nm, cur)
        if s:
            sents.append(s)
        else:
            nodebt.append(nm)
    parts = []
    if not sents:
        total = fv(tl, 'totalDebt')
        s = card + ' ' + dstr(stmt) + ' tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz ' + amt(total) + ' TL' + APO + 'dir.'
        if lp:
            s = s + ' Son ödeme tarihiniz ' + dstr(lp) + ' olacaktır.'
        parts.append(s)
    else:
        if today is not None and pdate(stmt) == today:
            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        parts.append(card + ' ' + dstr(stmt) + ' tarihli ekstre bilgileri.')
        parts.extend(sents)
        if nodebt:
            parts.append(joinn(nodebt) + ' borcunuz bulunmamaktadır.')
        d = pdate(lp)
        if d is not None:
            if today is not None and d == today:
                parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            elif today is not None and d < today:
                parts.append('Son ödeme tarihiniz geçmiş. Toplam borcunuz ' + amt(fv(tl, 'totalDebt')) + ' TL' + APO + 'dir.')
            else:
                parts.append('Borçlarınız için son ödeme tarihiniz ' + dstr(lp) + APO + 'dir.')
    parts = [p for p in parts if p]
    if sents:
        idx = 0
        for i, p in enumerate(parts):
            if p.endswith('tarihli ekstre bilgileri.'):
                idx = i
        return ' '.join(parts[:idx + 1]), ' '.join(parts[idx + 1:]), offer, email_ok
    return ' '.join(parts), '', offer, email_ok

try:
    card_part, figs_part, offer_part, ok = main()
except Exception:
    card_part, figs_part, offer_part, ok = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.', '', '', '0'
vars['debt_card'] = card_part
vars['debt_figs'] = figs_part
vars['debt_offer'] = offer_part
vars['has_figs'] = '1' if figs_part else '0'
vars['email_ok'] = ok

