import json

def G(k):
    v = vars.get(k)
    if isinstance(v, str):
        try:
            return json.loads(v)
        except Exception:
            return v
    return v

def digits_words(s):
    names = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    return ' '.join(names[int(ch)] for ch in str(s) if ch.isdigit())

cards = G('cards')
if not isinstance(cards, list):
    cards = []
    _i = 0
    while _i < 20:
        _p = 'cards_list_response.data.data.cards.' + str(_i) + '.'
        if vars.get(_p + 'cardNumber') is None:
            break
        cards.append(dict(cardNumber=str(vars.get(_p + 'cardNumber') or ''), cardNumberLast4=str(vars.get(_p + 'cardNumberLast4') or ''), productName=str(vars.get(_p + 'productName') or ''), status=str(vars.get(_p + 'status') or ''), isMainCard=str(vars.get(_p + 'isMainCard') or '')))
        _i += 1
    if len(cards) == 0:
        cards = None
resp = G('cards_list_response')
st = ''
try:
    st = str(resp.get('status_code') or '')
except Exception:
    st = ''
if st == '':
    st = str(vars.get('cards_list_status_code') or '')
elig = []
if isinstance(cards, list):
    for c in cards:
        if isinstance(c, dict) and str(c.get('status')) == 'A' and str(c.get('isMainCard')).lower() == 'true':
            elig.append(c)
if st == '404' or 'bulunamad' in str(resp):
    state = 'none'
elif not isinstance(cards, list):
    state = 'error'
elif len(elig) == 0:
    state = 'none'
elif len(elig) == 1:
    state = 'one'
else:
    state = 'multi'
vars['card_state'] = state
vars['card_choice'] = ''
vars['choice_tries'] = '0'
vars['elig_cards'] = json.dumps(elig, ensure_ascii=False)
vars['card_question'] = ''
if state == 'one':
    c = elig[0]
    vars['chosen_card_number'] = str(c.get('cardNumber') or '')
    vars['chosen_card_name'] = str(c.get('productName') or '').strip()
    vars['chosen_last4'] = str(c.get('cardNumberLast4') or '')
elif state == 'multi':
    opts = []
    for c in elig[:2]:
        nm = str(c.get('productName') or '').strip()
        if nm == '':
            nm = 'sonu ' + digits_words(c.get('cardNumberLast4') or '') + ' ile biten kart'
        opts.append(nm)
    vars['card_question'] = 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + opts[0] + ' veya ' + opts[1] + ' diyebilirsiniz.'
